target.css:
:root {
  --bg: #fffdf5;
  --border: #c8b87a;
  --header-bg: #2d5a3d;
  --header-text: #f0f7f2;
  --latin-text: #a8d5b5;
  --badge-bg: #f4a823;
  --badge-text: #3a2800;
  --label-color: #7a8c7e;
  --value-color: #1e2e22;
  --footer-bg: #eef5f0;
  --confirmed-color: #2d8a4e;
  --divider: #d6e8da;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
}

.sighting-tag {
  background-color: var(--bg);
  border: 2px solid var(--border);
  border-radius: 12px;
  width: 340px;
  overflow: hidden;
}

.tag-header {
  background-color: var(--header-bg);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 14px;
}

.tag-icon {
  font-size: 28px;
  line-height: 1;
}

.tag-title {
  flex: 1;
}

.species-name {
  color: var(--header-text);
  font-size: 18px;
  font-weight: 700;
  margin: 0;
  line-height: 1.2;
}

.latin-name {
  color: var(--latin-text);
  font-size: 12px;
  font-weight: 400;
  margin: 0;
  font-style: italic;
}

.status-badge {
  background-color: var(--badge-bg);
  color: var(--badge-text);
  font-size: 11px;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 20px;
}

.tag-details {
  padding: 10px 14px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.detail-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid var(--divider);
  padding-bottom: 6px;
}

.detail-item:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

.detail-label {
  font-size: 12px;
  color: var(--label-color);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.detail-value {
  font-size: 13px;
  color: var(--value-color);
  font-weight: 500;
}

.tag-footer {
  background-color: var(--footer-bg);
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 14px;
  border-top: 1px solid var(--divider);
}

.observer-label {
  font-size: 11px;
  color: var(--label-color);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.observer-name {
  font-size: 13px;
  color: var(--value-color);
  font-weight: 600;
  flex: 1;
}

.confidence {
  font-size: 12px;
  color: var(--confirmed-color);
  font-weight: 700;
}

